#include <array>
#include <cstddef>
#include <iostream>
#include <optional>
class Ring {
    std::array<int,3> slots_{};
    std::size_t head_ = 0, count_ = 0;
public:
    bool push(int value) {
        if (count_ == slots_.size()) return false;
        slots_[(head_+count_) % slots_.size()] = value;
        ++count_;
        return true;
    }
    std::optional<int> pop() {
        if (count_ == 0) return std::nullopt;
        const int value = slots_[head_];
        head_ = (head_+1) % slots_.size();
        --count_;
        return value;
    }
};
int main() {
    Ring queue;
    if (!queue.push(10) || !queue.push(20)) return 1;
    const auto removed = queue.pop();
    if (!removed || !queue.push(30) || !queue.push(40)) return 2;
    if (queue.push(50)) return 3;
    const auto a = queue.pop(), b = queue.pop(), c = queue.pop();
    if (!a || !b || !c || queue.pop()) return 4;
    std::cout << "removed=" << *removed << " queued="
              << *a << ',' << *b << ',' << *c << '\n';
}

#include <iostream>
#include <memory>
#include <utility>
int main() {
    // One-thread ownership model: no concurrent queue is claimed.
    std::unique_ptr<int> slot;
    bool closed = false;
    const auto push = [&](std::unique_ptr<int>& item) {
        if (closed || slot || !item) return false;
        slot = std::move(item);
        return true;
    };
    auto first = std::make_unique<int>(7);
    auto second = std::make_unique<int>(9);
    const bool accepted = push(first);
    const bool full_rejected = !push(second);
    closed = true;
    auto drained = std::move(slot);
    const bool closed_rejected = !push(second);
    std::cout << std::boolalpha << "accepted=" << accepted
              << " caller-empty=" << !first << '\n';
    std::cout << "full-rejected=" << full_rejected << " retained=" << *second << '\n';
    std::cout << "drained=" << *drained << " closed-rejected=" << closed_rejected << '\n';
}

